/* OTA UI-патч v7 — фикс по owner (5120) «Гпу мем не пишет»:
     На 17U kgsl печатает gpuaddr голым hex (без 0x, %p) а размер — в 3-й колонке (useraddr во 2-й),
     старый парсер суммировал f[1] под гейтом f[0]~/^0x/ → не совпадало ничего, gmem=0. page_alloc-sysfs
     на 17U тоже нет. ФИКС: kgsl_mem_sum() — устойчивый парс по инварианту «размер kgsl всегда кратен
     4096» (page-aligned) + мультирут (debugfs + хардпуть) + диаг-сайдкар gpumem.dbg. Новый бинарь
     доставляется этим OTA (гейт bin/.fpsd_ver=14 → переустановит; если демон запущен — перезапуск).
   Несёт в себе всё из v6: (A) fpsd сам монтирует debugfs после ребута; (B) частота оверлея 1 сек
   (PERIOD_MS/NPU_MS=1000, APK tick=1000мс); (C) i18n вкладки FPS по языку системы (en/zh, ru — источник).
   Демон fpsd доставляется кусками base64 в файл (обход MAX_ARG_STRLEN) + base64 -d, гейт по версии
   (bin/.fpsd_ver=14), БЕЗ автозапуска. Старый fps_helper.sh/fps_boot.sh/автозапуск сносятся дешёвой
   inline-чисткой на каждом заходе (идемпотентно). Идемпотентно (window.__fpsV7). Fail-safe. */
(function(){
  if (window.__fpsV7) return; window.__fpsV7 = 1;
  var MOD = '/data/adb/modules/enchaned-disable-thermal-universal';
  var BIN = MOD + '/bin/fpsd';           // нативный Rust-демон метрик
  var PKG = 'com.furry.fpsmon';
  var SVC = PKG + '/.OverlayService';
  var TMPB64 = '/data/local/tmp/.fpsd_b64';
  var FPSD_CHUNKS = [
    '',
    '',
    '',
    '',
    '',
    '',
    '',
    '',
    '',
    ''
  ];     // массив base64-кусков ELF fpsd — билдер подставляет

  // всегда-чистка: убрать любой старый автозапуск + погасить старый shell-хелпер (дёшево, идемпотентно)
  var CLEANUP =
    "P='"+MOD+"/post-fs-data.sh'; " +
    "if [ -f \"$P\" ] && grep -qE 'fps_boot\\.sh|# --- FPS' \"$P\"; then " +
      "grep -vE 'fps_boot\\.sh|# --- FPS' \"$P\" > \"$P.t\" && mv -f \"$P.t\" \"$P\" && chmod 0755 \"$P\"; fi; " +
    "pkill -f 'enchaned-disable-thermal-universal/fps_helper.sh' 2>/dev/null; " +
    "pkill -f 'fpsmon:cycstream' 2>/dev/null; pkill -f 'fpsmon:npustream' 2>/dev/null; " +
    "rm -f '"+MOD+"/fps_boot.sh' '"+MOD+"/fps_helper.sh' '"+MOD+"/.fps_v2' '"+MOD+"/.fps_off' 2>/dev/null; echo cleaned";

  // декодер: из накопленного файла base64 → bin/fpsd (rename, обход ETXTBSY), маркер версии, чистка.
  // v7: если демон был запущён (по pidfile) — перезапустить после свопа, чтобы новый парс gmem заработал сразу.
  var INSTALL_SH =
    "MOD='"+MOD+"'; BIN=\"$MOD/bin/fpsd\"; VER=14; SRC='"+TMPB64+"'; PF=/data/local/tmp/fpsmon/fpsd.pid; " +
    "[ -d \"$MOD\" ] || { echo no-mod; exit 1; }; mkdir -p \"$MOD/bin\"; " +
    "if [ -f \"$MOD/bin/.fpsd_ver\" ] && [ \"$(cat \"$MOD/bin/.fpsd_ver\" 2>/dev/null)\" = \"$VER\" ] && [ -x \"$BIN\" ]; then rm -f \"$SRC\"; echo current; exit 0; fi; " +
    "[ -s \"$SRC\" ] || { echo no-src; exit 1; }; " +
    "WAS=0; [ -f \"$PF\" ] && kill -0 \"$(cat \"$PF\" 2>/dev/null)\" 2>/dev/null && WAS=1; " +
    "[ -x \"$BIN\" ] && \"$BIN\" stop >/dev/null 2>&1; " +
    "base64 -d \"$SRC\" > \"$MOD/bin/fpsd.new\"; " +
    "[ -s \"$MOD/bin/fpsd.new\" ] || { echo fpsd-empty; rm -f \"$MOD/bin/fpsd.new\" \"$SRC\"; exit 1; }; " +
    "chmod 0755 \"$MOD/bin/fpsd.new\"; mv -f \"$MOD/bin/fpsd.new\" \"$BIN\"; " +
    "echo \"$VER\" > \"$MOD/bin/.fpsd_ver\"; rm -f \"$SRC\"; " +
    "[ \"$WAS\" = 1 ] && \"$BIN\" start >/dev/null 2>&1; echo installed";

  // ── root-exec поверх KernelSU WebUI ──
  function kexec(cmd){
    return new Promise(function(resolve){
      try {
        var ksu = window.ksu;
        if (!ksu || typeof ksu.exec !== 'function'){ resolve({errno:-1, stdout:'', stderr:'no-ksu'}); return; }
        var cb = 'fpscb7_' + Date.now() + '_' + Math.floor(Math.random()*1e6);
        var done = false;
        window[cb] = function(errno, stdout, stderr){
          if (done) return; done = true;
          try { delete window[cb]; } catch(e){ window[cb] = undefined; }
          if (errno && typeof errno === 'object') { resolve(errno); return; }
          resolve({errno:errno, stdout:stdout||'', stderr:stderr||''});
        };
        ksu.exec(cmd, JSON.stringify({}), cb);
        setTimeout(function(){ if(!done){ done=true; try{delete window[cb];}catch(e){} resolve({errno:-2, stdout:'', stderr:'timeout'}); } }, 12000);
      } catch(e){ resolve({errno:-1, stdout:'', stderr:String(e)}); }
    });
  }

  // ───────────────────────── i18n (self-contained, ru — источник) ─────────────────────────
  // язык берём тем же путём, что бинар (loadI18n читает <MOD>/locale), fallback — navigator.language.
  var LANG = 'en';                       // безопасный дефолт до резолва
  function normLang(s){
    s = String(s || '').trim().toLowerCase();
    if (!s) return '';
    if (s.indexOf('ru') === 0) return 'ru';
    if (s.indexOf('zh') === 0) return 'zh';
    if (s.indexOf('en') === 0) return 'en';
    return s.split(/[-_]/)[0];
  }
  function resolveLang(){
    return new Promise(function(resolve){
      var fb = normLang(navigator.language || navigator.userLanguage || 'en') || 'en';
      var done = false;
      function finish(v){ if (done) return; done = true; resolve(v); }
      setTimeout(function(){ finish(fb); }, 800);   // hard-fallback: без ksu-моста не ждём вечно
      kexec("cat '"+MOD+"/locale' 2>/dev/null").then(function(r){
        var v = normLang(r && r.stdout);
        finish(v || fb);
      }, function(){ finish(fb); });
    });
  }
  var DICT = {
    en: {
      'Оверлей поверх игры': 'Overlay on top of the game',
      'FPS оверлей': 'FPS overlay',
      'Поверх игры и в шторке': 'On top of the game and in the shade',
      'Показывать оверлей': 'Show overlay',
      'То же — плиткой в шторке': 'Same — as a quick-settings tile',
      'Плитка «FPS оверлей» делает ровно это. При первом включении KernelSU один раз спросит root для fpsmon — разреши, дальше без запросов.':
        'The «FPS overlay» tile does exactly this. On first use KernelSU will ask for root for fpsmon once — allow it, no prompts afterwards.',
      'активен — считает поверх игры': 'active — counting over the game',
      'выключен': 'off'
    },
    zh: {
      'Оверлей поверх игры': '游戏悬浮窗',
      'FPS оверлей': 'FPS 悬浮窗',
      'Поверх игры и в шторке': '游戏上层及通知栏',
      'Показывать оверлей': '显示悬浮窗',
      'То же — плиткой в шторке': '相同功能 — 通知栏磁贴',
      'Плитка «FPS оверлей» делает ровно это. При первом включении KernelSU один раз спросит root для fpsmon — разреши, дальше без запросов.':
        '「FPS 悬浮窗」磁贴的功能与此完全相同。首次开启时 KernelSU 会为 fpsmon 请求一次 root 权限 — 请允许，之后不再询问。',
      'активен — считает поверх игры': '已启用 — 正在游戏上层计数',
      'выключен': '已关闭'
    }
  };
  function tr(s){
    if (LANG === 'ru' || !s) return s;
    var d = DICT[LANG] || DICT.en;
    var k = String(s).trim();
    if (!k) return s;
    return d[k] || s;
  }
  function localize(root){
    if (!root || LANG === 'ru') return;
    try {
      var w = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, null);
      var nodes = [], n;
      while ((n = w.nextNode())) nodes.push(n);
      for (var i=0;i<nodes.length;i++){
        var t = nodes[i], v = (t.nodeValue || '');
        var trim = v.trim();
        if (!trim) continue;
        var nv = tr(trim);
        if (nv !== trim) t.nodeValue = v.replace(trim, nv);
      }
    } catch(e){}
  }
  function applyI18n(){
    if (LANG === 'ru') return;
    localize(byId('tab-fps'));
    localize(byId('nav-fps'));   // 'FPS' не в DICT → метка навигации не меняется
  }

  // положить fpsd: записать base64 кусками в файл (каждый <128КБ, обход MAX_ARG_STRLEN) → decode
  function installBackend(){
    try {
      var chain = kexec("rm -f '"+TMPB64+"'");
      FPSD_CHUNKS.forEach(function(c){
        chain = chain.then(function(){ return kexec("printf '%s' '"+c+"' >> '"+TMPB64+"'"); });
      });
      return chain.then(function(){ return kexec(INSTALL_SH); });
    } catch(e){ return Promise.resolve({errno:-1}); }
  }

  // мастер-выключатель «оверлей поверх игры».
  function monStart(){
    return kexec(
      "'"+BIN+"' start >/dev/null 2>&1; " +
      "appops set "+PKG+" SYSTEM_ALERT_WINDOW allow 2>/dev/null; " +
      "am start-foreground-service -n "+SVC+" 2>/dev/null; echo started"
    );
  }
  function monStop(){
    return kexec(
      "am stopservice -n "+SVC+" 2>/dev/null; " +
      "'"+BIN+"' stop >/dev/null 2>&1; echo stopped"
    );
  }
  function monState(){
    return kexec("dumpsys activity services "+PKG+" 2>/dev/null | grep -c OverlayService").then(function(r){
      var n = parseInt(((r.stdout||'0').match(/\d+/)||['0'])[0], 10) || 0;
      return n>0 ? 'on' : 'off';
    });
  }

  function byId(id){ return document.getElementById(id); }
  function E(tag, css, txt){ var e=document.createElement(tag); if(css) e.style.cssText=css; if(txt!=null) e.textContent=txt; return e; }

  function purgeOld(){
    try {
      var kill = [];
      var sel = document.querySelectorAll('[id="nav-fps"],[id="tab-fps"],[data-target="tab-fps"]');
      for (var i=0;i<sel.length;i++) kill.push(sel[i]);
      for (var k=0;k<kill.length;k++){ var e=kill[k]; if(e&&e.parentNode) e.parentNode.removeChild(e); }
    } catch(e){}
  }

  function setSwitch(on){
    var t = byId('fpsToggle'); if(t) t.checked = !!on;
    var st = byId('fpsState'); if(st) st.textContent = tr(on ? 'активен — считает поверх игры' : 'выключен');
  }

  // вкладка нативными классами термала → liquid-glass blur применяется как везде
  function buildPane(){
    var pane = E('div'); pane.id='tab-fps'; pane.className='view'; pane.style.cssText='padding:16px 14px 90px;';
    pane.innerHTML =
      '<div class="slbl">Оверлей поверх игры</div>' +
      '<div class="card">' +
        '<div class="card-h">' +
          '<div class="card-ic" style="background:var(--accent-bg)">🎮</div>' +
          '<div><div class="card-t">FPS оверлей</div><div class="card-s">Поверх игры и в шторке</div></div>' +
        '</div>' +
        '<div class="card-body">' +
          '<div class="r" style="border-bottom:none">' +
            '<div class="r-ic" style="background:var(--blue-bg)">📊</div>' +
            '<div class="r-info">' +
              '<div class="r-label">Показывать оверлей</div>' +
              '<div class="r-desc" id="fpsState">—</div>' +
            '</div>' +
            '<div class="r-ctrl"><label class="tg"><input type="checkbox" id="fpsToggle"><div class="tg-t"></div><div class="tg-k"></div></label></div>' +
          '</div>' +
        '</div>' +
      '</div>' +
      '<div class="card">' +
        '<div class="card-body" style="padding-top:14px;padding-bottom:14px">' +
          '<div class="r" style="border-bottom:none;padding:2px 0">' +
            '<div class="r-ic" style="background:var(--green-bg)">🪟</div>' +
            '<div class="r-info">' +
              '<div class="r-label" style="font-size:14px">То же — плиткой в шторке</div>' +
              '<div class="r-desc">Плитка «FPS оверлей» делает ровно это. При первом включении KernelSU один раз спросит root для fpsmon — разреши, дальше без запросов.</div>' +
            '</div>' +
          '</div>' +
        '</div>' +
      '</div>';
    return pane;
  }

  function wireToggle(){
    var t = byId('fpsToggle'); if(!t || t.__wired) return; t.__wired = 1;
    t.addEventListener('change', function(){
      var want = t.checked;
      t.disabled = true;
      (want ? monStart() : monStop()).then(function(){
        return monState();   // подтвердить фактическое (оверлей мог не подняться без лицензии/разрешения)
      }).then(function(st){ setSwitch(st==='on'); t.disabled = false; })
        .catch(function(){ setSwitch(!want); t.disabled = false; });
    });
  }

  function activateFps(){
    try {
      var vs=document.querySelectorAll('.view'); for(var i=0;i<vs.length;i++) vs[i].classList.remove('active');
      var ns=document.querySelectorAll('.ni'); for(var k=0;k<ns.length;k++) ns[k].classList.remove('active');
      var p=byId('tab-fps'), n=byId('nav-fps'); if(p)p.classList.add('active'); if(n)n.classList.add('active');
      monState().then(function(st){ setSwitch(st==='on'); }).catch(function(){});
    } catch(e){}
  }

  function inject(){
    try {
      var navRef = byId('nav-thermal'), viewRef = byId('tab-thermal');
      if (!navRef || !viewRef || !navRef.parentNode || !viewRef.parentNode) return false;
      if (!byId('nav-fps')){
        var b = E('button'); b.className='ni'; b.id='nav-fps'; b.setAttribute('data-target','tab-fps');
        b.innerHTML = '<span class="ni-ic">🎮</span><span class="ni-lb">FPS</span><div class="ni-dot"></div>';
        b.addEventListener('click', function(ev){ ev.preventDefault(); ev.stopPropagation(); activateFps(); });
        navRef.parentNode.insertBefore(b, navRef.nextSibling);
      }
      if (!byId('tab-fps')){
        viewRef.parentNode.insertBefore(buildPane(), viewRef.nextSibling);
        wireToggle();
        applyI18n();   // перевести только что созданную панель под текущий LANG
      }
      return true;
    } catch(e){ return false; }
  }

  function wireAway(){
    try {
      document.addEventListener('click', function(ev){
        var t = ev.target && ev.target.closest ? ev.target.closest('.ni') : null;
        if (t && t.id !== 'nav-fps'){ var p=byId('tab-fps'), n=byId('nav-fps'); if(p)p.classList.remove('active'); if(n)n.classList.remove('active'); }
      }, true);
    } catch(e){}
  }

  function ensureBackend(){
    kexec(CLEANUP).catch(function(){});
    kexec("cat '"+MOD+"/bin/.fpsd_ver' 2>/dev/null; echo").then(function(r){
      if (((r.stdout||'').trim()) !== '14') installBackend().catch(function(){});
    }).catch(function(){ installBackend().catch(function(){}); });
  }

  function boot(){
    purgeOld();       // убрать узлы прошлых версий
    inject();
    wireAway();
    ensureBackend();
    monState().then(function(st){ setSwitch(st==='on'); }).catch(function(){ setSwitch(false); });
  }

  // когда язык определился — перевести панель и обновить строку состояния под язык
  resolveLang().then(function(l){
    LANG = l || 'en';
    applyI18n();
    monState().then(function(st){ setSwitch(st==='on'); }).catch(function(){});
  });

  if (document.readyState !== 'loading') boot();
  else document.addEventListener('DOMContentLoaded', boot);
  var tries=0, iv=setInterval(function(){ if (byId('tab-fps') || ++tries>40){ clearInterval(iv); } else { inject(); } }, 500);
})();

/* ===== 4.9.19 — activation welcome + supplemental activation-window i18n =====
   Owner msg 5435, two asks on the license activation window (#claudeActOverlay):
   (B) show a localized greeting the moment a license activates.
   (C) the activation window must translate by system language; the base DICT (4.9.1,
       __actOvScope) covers the happy path but every fplic error is rendered through
       fail() as 'Лицензия не привязана: ' + reason, and reason itself can be composite
       ('нет отпечатка железа (liblogic --fp): ' + (fp||'пусто')). None of those keys
       exist in the base DICT, so they leak Russian for en/zh users.

   Self-contained on purpose: it runs both appended to base script.js AND re-applied via
   UI-OTA as `(new Function(js)).call(window)`, where the base DICT/tr/localize closures are
   NOT reachable. Only touches window globals + #claudeActOverlay/#claudeActErr, guards every
   exec-bridge call (c/MOD), and is idempotent via its own window flag. No body-wide observer
   (4.8.7 lesson — that broke the chat) — a scoped 700ms poll only. */
(function(){
  if (window.__actWelcomeI18n) return; window.__actWelcomeI18n = true;

  // ── language: same pipeline as base i18n (<MOD>/locale via c(), else navigator.language) ──
  var LANG = 'en';
  function normalize(s){
    s = String(s || '').trim().toLowerCase(); if (!s) return '';
    if (s.indexOf('ru') === 0) return 'ru';
    if (s.indexOf('zh') === 0) return 'zh';
    if (s.indexOf('en') === 0) return 'en';
    return s.split(/[-_]/)[0];
  }
  function resolveLang(cb){
    var fb = normalize(navigator.language || navigator.userLanguage || 'en') || 'en';
    var done = false; function fin(v){ if (done) return; done = true; cb(v || fb); }
    setTimeout(function(){ fin(fb); }, 800);
    try {
      if (typeof c === 'function' && typeof MOD === 'string') {
        c('cat "' + MOD + '/locale" 2>/dev/null').then(function(r){ fin(normalize(r && r.stdout)); },
                                                        function(){ fin(fb); });
        return;
      }
    } catch(e){}
    fin(fb);
  }

  // ── (C) leaf strings the base DICT misses (all reachable inside #claudeActErr) ──
  var EXTRA = {
    en: {
      'нет связи с сервером лицензий': 'no connection to the license server',
      'отказ': 'denied',
      'пусто': 'empty'
    },
    zh: {
      'нет связи с сервером лицензий': '无法连接许可证服务器',
      'отказ': '已拒绝',
      'пусто': '空'
    }
  };
  // composite prefixes; the tail is translated recursively (it can itself be composite)
  var PREFIX = {
    en: [
      ['Лицензия не привязана: ', 'License not bound: '],
      ['нет отпечатка железа (liblogic --fp): ', 'no hardware fingerprint (liblogic --fp): ']
    ],
    zh: [
      ['Лицензия не привязана: ', '许可证未绑定：'],
      ['нет отпечатка железа (liblogic --fp): ', '无硬件指纹 (liblogic --fp)：']
    ]
  };
  function trExtra(s){
    if (LANG === 'ru' || !s) return s;
    var d = EXTRA[LANG] || EXTRA.en;
    var k = String(s).trim(); if (!k) return s;
    if (d[k]) return d[k];
    var pfx = PREFIX[LANG] || PREFIX.en;
    for (var i = 0; i < pfx.length; i++){
      if (k.indexOf(pfx[i][0]) === 0){
        return pfx[i][1] + trExtra(k.slice(pfx[i][0].length));   // recurse into the dynamic tail
      }
    }
    return s;   // unknown (e.g. server-supplied reason) — leave as-is
  }
  function localizeExtra(){
    if (LANG === 'ru') return;
    try {
      var seen = [], roots = [];
      var ov = document.getElementById('claudeActOverlay'); if (ov) roots.push(ov);
      var er = document.getElementById('claudeActErr');
      if (er && roots.indexOf(er) < 0 && !(ov && ov.contains && ov.contains(er))) roots.push(er);
      for (var ri = 0; ri < roots.length; ri++){
        var w = document.createTreeWalker(roots[ri], NodeFilter.SHOW_TEXT, null), n;
        while ((n = w.nextNode())){
          if (seen.indexOf(n) >= 0) continue; seen.push(n);
          var v = (n.nodeValue || ''), trim = v.trim();
          if (!trim) continue;
          var nv = trExtra(trim);
          if (nv !== trim) n.nodeValue = v.replace(trim, nv);
        }
      }
    } catch(e){}
  }

  // ── (B) welcome the moment a license activates ──
  var WELCOME = {
    ru: { t: 'Добро пожаловать! 🐾', b: 'Лицензия активирована — AI-ассистент разблокирован. Спрашивайте что угодно про термо-модуль, устройство и настройки.' },
    en: { t: 'Welcome aboard! 🐾', b: 'Your license is active — the AI assistant is unlocked. Ask me anything about the thermal module, your device and settings.' },
    zh: { t: '欢迎！🐾', b: '许可证已激活 — AI 助手已解锁。有关散热模块、设备和设置的任何问题都可以问我。' }
  };
  function showWelcome(){
    try {
      if (document.getElementById('actWelcomeCard')) return;                 // idempotent
      var m = WELCOME[LANG] || WELCOME.en;
      var wrap = document.createElement('div');
      wrap.id = 'actWelcomeCard';
      wrap.style.cssText = 'position:fixed;left:14px;right:14px;bottom:90px;z-index:2147483646;'
        + 'display:flex;align-items:flex-start;gap:10px;max-width:520px;margin:0 auto;'
        + 'background:rgba(24,20,34,0.96);border:1px solid rgba(139,92,246,0.45);'
        + 'backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);'
        + 'border-radius:16px;padding:13px 15px;box-shadow:0 12px 38px rgba(0,0,0,0.5);'
        + 'opacity:0;transform:translateY(8px);transition:opacity .28s ease,transform .28s ease';
      var txt = document.createElement('div');
