    var chatInflight=0, replyWaitUntil=0, graceUntil=0, phase=0;
    function busy(){ var t=Date.now(); return chatInflight>0 || t<replyWaitUntil || t<graceUntil; }
    var _f = window.fetch;
    if (typeof _f === 'function') {
      window.fetch = function(input, init){
