        var txt=document.createElement('span'); txt.className='otaWorkTxt';
        b.appendChild(dot); b.appendChild(txt);
      }
      if(box.lastChild!==b) box.appendChild(b);
      return b;
    }
    function removeBubble(){ var b=document.getElementById(BID); if(b&&b.parentNode) b.parentNode.removeChild(b); }
    function tick(){
      try{
        phase=(phase+1)&15;
        var status=document.getElementById(STATUS);
        var nativeOn=status&&status.textContent&&status.textContent.trim();
        if(busy()&&!nativeOn){
