  function coreAgg(nested, mode){
    if(!Array.isArray(nested)||!nested.length) return [];
    var cores=nested.map(function(c){ return Array.isArray(c)?c.map(num):[]; });
    var n=0; cores.forEach(function(c){ if(c.length>n)n=c.length; });
    var out=[];
    for(var i=0;i<n;i++){
      var mx=0, sum=0, cnt=0;
      cores.forEach(function(c){ var v=num(c[i]); if(mode==='max'){ if(v>mx)mx=v; } else { sum+=v; cnt++; } });
      out.push(mode==='max'?mx:(mode==='sum'?sum:(cnt?sum/cnt:0)));
    }
    return out;
  }

