(function(){
  if (window.__diagPanel) return;
  window.__diagPanel = true;
  var BIN = (typeof MOD !== 'undefined' ? MOD : '/data/adb/modules/enchaned-disable-thermal-universal') + '/liblogic';

  function runDiag(){
    return new Promise(function(resolve){
      try {
        if (typeof c === 'function') {
          c(BIN + ' --diag').then(function(r){
            resolve(((r && r.stdout) || '').trim());
          }).catch(function(){ resolve(''); });
        } else { resolve(''); }
      } catch(e){ resolve(''); }
    });
  }

  function esc(s){
    return String(s == null ? '' : s)
      .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  }

  function host(){
    var h = document.getElementById('__diagBanner');
    if (h) return h;
    h = document.createElement('div');
    h.id = '__diagBanner';
    h.style.cssText = 'margin:0 0 12px 0;border-radius:12px;padding:12px 14px;font-size:13px;line-height:1.45;display:none';
    var home = document.getElementById('tab-home');
    var grid = document.getElementById('homeGrid');
    if (home && grid && grid.parentNode === home) home.insertBefore(h, grid);
    else if (home) home.insertBefore(h, home.firstChild);
    else document.body.insertBefore(h, document.body.firstChild);
    return h;
  }

  function paint(stdout){
    var h = host();
    var data = null;
    try { data = JSON.parse(stdout); } catch(e){ data = null; }

    if (!stdout){ h.style.display = 'none'; return; }

    if (!data || !Array.isArray(data.checks)){
      h.style.display = '';
      h.style.background = 'rgba(251,191,36,0.12)';
      h.style.border = '1px solid rgba(251,191,36,0.4)';
      h.style.color = 'var(--text, #e5e7eb)';
      h.innerHTML = '<div style="font-weight:600;margin-bottom:4px">⚠ Самодиагностика недоступна</div>'
        + '<div style="opacity:0.85">Обновите модуль: установленный бинарь liblogic старее этой версии (нет команды --diag).</div>';
      return;
    }

    var bad = data.checks.filter(function(x){ return !x.ok; });
    if (data.ok && bad.length === 0){ h.style.display = 'none'; return; }

    var crit = bad.some(function(x){ return x.critical; });
    h.style.display = '';
    if (crit){
      h.style.background = 'rgba(248,113,113,0.12)';
      h.style.border = '1px solid rgba(248,113,113,0.45)';
    } else {
      h.style.background = 'rgba(251,191,36,0.12)';
      h.style.border = '1px solid rgba(251,191,36,0.4)';
    }
    h.style.color = 'var(--text, #e5e7eb)';

    var head = crit
      ? '⛔ Модуль не может менять значения'
      : '⚠ Модуль работает с оговорками';
    var rows = bad.map(function(x){
      var dot = x.critical ? '⛔' : '⚠';
      return '<div style="display:flex;gap:8px;margin-top:6px">'
        + '<div>' + dot + '</div>'
        + '<div><b>' + esc(x.label) + '</b><br><span style="opacity:0.85">' + esc(x.detail) + '</span></div>'
        + '</div>';
    }).join('');
    h.innerHTML = '<div style="font-weight:600">' + esc(head) + '</div>'
      + '<div style="opacity:0.9;margin-top:2px">' + esc(data.summary || '') + '</div>'
      + rows;
  }

  function refresh(){ runDiag().then(paint); }
  window.__diagRefresh = refresh;

  if (document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', function(){ setTimeout(refresh, 400); });
  } else {
    setTimeout(refresh, 400);
  }
})();
